DO $do$
DECLARE
  cvc_count int;
  act_count int;
BEGIN
  SELECT jsonb_array_length(template_fields) INTO cvc_count
    FROM lookup_document_type WHERE key = 'CONTRACT_VANZARE';
  SELECT jsonb_array_length(template_fields) INTO act_count
    FROM lookup_document_type WHERE key = 'ACT_ADITIONAL';
  -- A missing row leaves a NULL count, not a zero: the UPDATE matched nothing
  -- and the form was never written, which is the case most worth shouting
  -- about. IS DISTINCT FROM catches it; `<>` would not.
  IF cvc_count IS DISTINCT FROM 53 OR act_count IS DISTINCT FROM 20 THEN
    RAISE EXCEPTION 'migration_085: expected 53 / 20 template fields on CONTRACT_VANZARE / ACT_ADITIONAL, got % / %',
      cvc_count, act_count;
  END IF;
  RAISE NOTICE 'migration_085: CONTRACT_VANZARE now carries % template field(s), ACT_ADITIONAL %.',
    cvc_count, act_count;
END $do$;
